node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const rows = db.prepare('SELECT * FROM ts_reminders').all();
console.log('Reminders (' + rows.length + ' total):');
rows.forEach(r => {
  // Convert timestamps to readable dates
  if (r.reminder_timestamp) {
    r.reminder_time_readable = new Date(r.reminder_timestamp * 1000).toISOString();
  }
  if (r.creation_timestamp) {
    r.creation_time_readable = new Date(r.creation_timestamp * 1000).toISOString();
  }
  console.log(JSON.stringify(r, null, 2));
  console.log('---');
});
db.close();
"
